// Читает marker последней обработанной пачки обновлений.
// n8n хранит его в статических данных workflow между запусками.
const store = $getWorkflowStaticData('global');
return [{ json: { marker: store.marker ?? null } }];

// Разбирает ответ GET /updates:
//  1. сохраняет новый marker (подтверждение обработки на стороне MAX);
//  2. отбрасывает всё, кроме личных диалогов, — боевые групповые чаты не трогаем;
//  3. приводит message_created и message_callback к одной плоской структуре.
const store = $getWorkflowStaticData('global');
const res = $input.first().json ?? {};
const updates = res.updates ?? [];

if (res.marker !== undefined && res.marker !== null) {
  store.marker = res.marker;
}

const ONLY_DIALOGS = true; // защита: false выпустит бота в групповые чаты

const out = [];
for (const u of updates) {
  const msg = u.message ?? {};
  const rec = msg.recipient ?? {};
  const cb = u.callback ?? {};
  const sender = cb.user ?? msg.sender ?? {};

  if (ONLY_DIALOGS && rec.chat_type !== 'dialog') continue;
  if (sender.is_bot) continue;

  const base = {
    chat_id: rec.chat_id ?? null,
    user_id: rec.user_id ?? sender.user_id ?? null,
    name: sender.first_name ?? sender.name ?? 'друг',
    update_type: u.update_type,
  };

  if (u.update_type === 'message_created') {
    out.push({ json: { ...base, kind: 'message', text: (msg.body?.text ?? '').trim(), payload: null, callback_id: null } });
  } else if (u.update_type === 'message_callback') {
    out.push({ json: { ...base, kind: 'callback', text: '', payload: cb.payload ?? '', callback_id: cb.callback_id ?? null } });
  } else if (u.update_type === 'bot_started') {
    out.push({ json: { ...base, kind: 'message', text: '/start', payload: null, callback_id: null } });
  }
}
return out;

// Ветка «эхо»: отдельный сценарий, не связанный с меню.
const ev = $json;
return [{
  json: {
    api_path: 'messages',
    api_query: { chat_id: String(ev.chat_id) },
    body: {
      text: '🔁 Вы написали: ' + ev.text.replace(/^эхо\s+/i, ''),
      format: 'markdown',
      attachments: [{ type: 'inline_keyboard', payload: { buttons: [[{ type: 'callback', text: '⬅️ В меню', payload: 'main' }]] } }],
    },
  },
}];

// ЕДИНСТВЕННОЕ место, где описано меню бота.
// Чтобы поменять кнопки — правьте объект MENU прямо в редакторе n8n
// и нажмите Save. Перезапуск контейнера не нужен.
//
// Типы кнопок MAX: callback | link | request_contact | request_geo_location | message | chat
const MENU = {
  main: {
    text: 'Привет, {name}! 👋\nЭто демо-бот, собранный целиком в n8n.\n\nВыберите раздел:',
    buttons: [
      [
        { type: 'callback', text: '📋 Каталог', payload: 'catalog' },
        { type: 'callback', text: 'ℹ️ О боте', payload: 'about' },
      ],
      [{ type: 'callback', text: '📞 Контакты', payload: 'contacts' }],
      [{ type: 'link', text: '🌐 Документация MAX', url: 'https://dev.max.ru/docs' }],
    ],
  },
  catalog: {
    text: '📋 *Каталог*\n\nВыберите товар:',
    buttons: [
      [
        { type: 'callback', text: 'Товар A — 100 ₽', payload: 'item:a' },
        { type: 'callback', text: 'Товар B — 250 ₽', payload: 'item:b' },
      ],
      [{ type: 'callback', text: '⬅️ Назад', payload: 'main' }],
    ],
  },
  about: {
    text: 'ℹ️ *О боте*\n\nСценарий целиком живёт в n8n: опрос Bot API MAX, разбор апдейтов, меню и отправка ответов. Кода в репозитории нет — только конфигурация.',
    buttons: [[{ type: 'callback', text: '⬅️ Назад', payload: 'main' }]],
  },
  contacts: {
    text: '📞 *Контакты*\n\nОставьте телефон, и мы перезвоним.',
    buttons: [
      [{ type: 'request_contact', text: '📱 Отправить контакт' }],
      [{ type: 'callback', text: '⬅️ Назад', payload: 'main' }],
    ],
  },
};

// Динамический экран: показывает, что содержимое можно строить на лету.
function screen(key, ev) {
  if (key.startsWith('item:')) {
    const code = key.slice(5).toUpperCase();
    return {
      text: `✅ Товар *${code}* добавлен в корзину.\nВремя: ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`,
      buttons: [[{ type: 'callback', text: '⬅️ В каталог', payload: 'catalog' }]],
    };
  }
  return MENU[key] ?? MENU.main;
}

const ev = $json;
const key = ev.kind === 'callback' ? (ev.payload || 'main') : 'main';
const scr = screen(key, ev);

const body = {
  text: scr.text.replace('{name}', ev.name),
  format: 'markdown',
  attachments: [{ type: 'inline_keyboard', payload: { buttons: scr.buttons } }],
};

// callback отвечаем через /answers — сообщение с кнопками меняется на месте.
// Обычное сообщение отправляем через /messages.
if (ev.kind === 'callback' && ev.callback_id) {
  return [{ json: { api_path: 'answers', api_query: { callback_id: ev.callback_id }, body: { message: body } } }];
}
return [{ json: { api_path: 'messages', api_query: { chat_id: String(ev.chat_id) }, body } }];
